const form=document.getElementById("paintForm"),result=document.getElementById("result"),material=document.getElementById("material"),rate=document.getElementById("rate");function setDefaults(){!material||!rate||(rate.value=material.value==="primer"?"100":"150")}material&&material.addEventListener("change",setDefaults),form&&form.addEventListener("submit",t=>{t.preventDefault();const n=parseFloat(document.getElementById("length").value)||0,s=parseFloat(document.getElementById("height").value)||0,l=parseInt(document.getElementById("coats").value,10)||1,e=parseFloat(document.getElementById("rate").value)||0,a=parseFloat(document.getElementById("canL").value)||0;if(n<=0||s<=0||e<=0||a<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите размеры поверхности, расход и объём банки больше нуля.</p>';return}const c=n*s,i=c*l*e/1e3,r=Math.ceil(i/a),m=material&&material.value==="primer";result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Площадь поверхности</span><span class="val">${fmt(c)} м²</span></div>
        <div class="item"><span>Слоёв</span><span class="val">${l}</span></div>
        <div class="item"><span>${m?"Грунтовки":"Краски"} (${fmt(e)} мл/м²·слой)</span><span class="val">${fmt(i)} л</span></div>
        <div class="item total"><span>Банок (${fmt(a)} л)</span><span class="val">${fmt(r)} шт</span></div>
      </div>
      <p class="hint" style="margin-top:14px">Значение расхода уточняйте на упаковке.</p>
    `});function fmt(t){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(t)}
